import type { VideoMetadata } from "@cap/database/types";

/**
 * Title-origin metadata for a NEWLY CREATED video.
 *
 * Pass the HUMAN-CHOSEN title if one exists — the file name the user picked
 * for an upload, Loom's own video title, a name typed in the recorder — or
 * null/undefined when the system fell back to a dated template ("data365
 * Recording - <date>", "Loom Import - <date>", ...).
 *
 * Only the template case is marked `titleAutoGenerated`, which is what later
 * allows the AI auto-title to replace it. A filename the user picked is the
 * USER'S CONTENT, not a machine name — marking it machine-derived made the AI
 * overwrite titles like "Q3 board meeting" (review finding #3, 2026-08-10).
 *
 * Creation sites must build the flag through this helper (a test enforces
 * that no creation site writes the raw literal), so the human/machine
 * decision lives in exactly one place.
 */
export function titleOriginMetadata(
	humanChosenTitle: string | null | undefined,
): Pick<VideoMetadata, "titleAutoGenerated"> {
	return humanChosenTitle?.trim() ? {} : { titleAutoGenerated: true };
}
